+        ctx.lineWidth = rimWidth * .017;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop - rimHeight * .008, rimWidth * .474, rimHeight * .475, 0, .08, Math.PI - .08);
+        ctx.stroke();
+        ctx.strokeStyle = 'rgba(21, 9, 8, .64)';
+        ctx.lineWidth = rimWidth * .025;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop + rimHeight * .018, rimWidth * .466, rimHeight * .446, 0, 0, TAU);
+        ctx.stroke();
+        ctx.strokeStyle = 'rgba(230, 119, 63, .21)';
+        ctx.lineWidth = rimWidth * .009;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop - rimHeight * .008, rimWidth * .49, rimHeight * .53, 0, .12, Math.PI - .12);
