+  </main>
+
+  <script>
+    (() => {
+      'use strict';
+
+      const canvas = document.getElementById('ramen-scene');
+      const ctx = canvas.getContext('2d');
+      const reduceQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
+      const pointer = { x: 0, y: 0, targetX: 0, targetY: 0 };
