+      let width = 0;
+      let height = 0;
+      let pixelRatio = 1;
+      let reducedMotion = reduceQuery.matches;
+      let frameId = 0;
+      let lastTime = 0;
+
+      const steam = Array.from({ length: 11 }, (_, index) => ({
+        phase: index * 1.71 + .4,
+        x: (index - 5) * .071 + Math.sin(index * 3.7) * .016,
+        height: .2 + (index % 4) * .045,
+        width: .065 + (index % 3) * .018,
+        speed: .18 + (index % 5) * .022,
+        alpha: .10 + (index % 4) * .018
+      }));
+
+      const noodles = Array.from({ length: 21 }, (_, index) => ({
+        x: -0.91 + (index / 20) * 1.82,
+        y: -.10 + Math.sin(index * 2.6) * .12,
+        bend: .05 + (index % 5) * .019,
+        phase: index * .83,
+        length: .48 + (index % 4) * .08
