+        // A few darker curls give the noodles depth against the glowing broth.
+        ctx.lineWidth = rimWidth * .009;
+        ctx.strokeStyle = 'rgba(117, 49, 17, .54)';
+        for (let index = 0; index < 8; index++) {
+          const x = cx + (-.72 + index * .19) * brothRX;
+          const y = brothY + (-.08 + (index % 4) * .075) * brothRY;
+          ctx.beginPath();
+          ctx.moveTo(x - rimWidth * .12, y);
+          ctx.quadraticCurveTo(x, y - rimWidth * .07, x + rimWidth * .12, y + rimWidth * .012);
+          ctx.stroke();
+        }
+        ctx.restore();
+      }
+
+      function drawTofu(x, y, size, rotation) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rotation);
+        const tofu = ctx.createLinearGradient(-size, -size, size, size);
+        tofu.addColorStop(0, '#f1c67d');
+        tofu.addColorStop(.55, '#d99a4d');
+        tofu.addColorStop(1, '#a9632b');
+        ctx.fillStyle = tofu;
+        roundRectPath(-size, -size * .62, size * 2, size * 1.24, size * .18);
+        ctx.fill();
+        ctx.strokeStyle = 'rgba(255, 229, 164, .36)';
+        ctx.lineWidth = size * .075;
+        ctx.stroke();
+        ctx.fillStyle = 'rgba(255, 223, 141, .27)';
+        ctx.fillRect(-size * .6, -size * .34, size * .44, size * .1);
+        ctx.restore();
+      }
+
+      function drawMushroom(x, y, size, rotation) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rotation);
+        const stem = ctx.createLinearGradient(-size * .3, 0, size * .34, 0);
+        stem.addColorStop(0, '#e8bf83');
+        stem.addColorStop(1, '#a76e3d');
+        ctx.fillStyle = stem;
+        ctx.beginPath();
+        ctx.ellipse(0, size * .31, size * .26, size * .42, 0, 0, TAU);
+        ctx.fill();
+        const cap = ctx.createRadialGradient(-size * .2, -size * .18, size * .05, 0, 0, size * .72);
+        cap.addColorStop(0, '#e8b879');
+        cap.addColorStop(.5, '#a96135');
+        cap.addColorStop(1, '#64301e');
+        ctx.fillStyle = cap;
+        ctx.beginPath();
+        ctx.ellipse(0, 0, size * .64, size * .3, 0, Math.PI, TAU);
+        ctx.fill();
+        ctx.strokeStyle = 'rgba(249, 203, 133, .24)';
+        ctx.lineWidth = size * .035;
+        ctx.stroke();
+        ctx.restore();
+      }
+
+      function drawGreens(cx, brothY, rimWidth, time) {
+        const sway = reducedMotion ? 0 : Math.sin(time * .9) * rimWidth * .008;
+        // Bok choy, tucked to the left so the bowl still reads as one silhouette.
+        ctx.save();
+        ctx.translate(cx - rimWidth * .27 + sway, brothY + rimWidth * .02);
+        ctx.rotate(-.24);
+        const leaf = ctx.createLinearGradient(0, -rimWidth * .21, rimWidth * .13, rimWidth * .15);
+        leaf.addColorStop(0, '#a5b65d');
+        leaf.addColorStop(.55, '#4b7139');
+        leaf.addColorStop(1, '#203d29');
+        ctx.fillStyle = leaf;
+        for (let index = 0; index < 4; index++) {
+          ctx.beginPath();
+          ctx.ellipse(index * rimWidth * .065, -rimWidth * (.04 + (index % 2) * .025), rimWidth * .075, rimWidth * .22, -.17 + index * .1, 0, TAU);
+          ctx.fill();
+        }
+        ctx.strokeStyle = 'rgba(221, 220, 133, .44)';
+        ctx.lineWidth = rimWidth * .014;
+        ctx.beginPath();
+        ctx.moveTo(rimWidth * .03, rimWidth * .16);
+        ctx.lineTo(rimWidth * .03, -rimWidth * .18);
+        ctx.stroke();
+        ctx.restore();
+
+        // Charred corn kernels.
+        ctx.fillStyle = '#e7b94f';
+        for (let index = 0; index < 7; index++) {
+          const angle = -.15 + index * .2;
+          const x = cx + Math.cos(angle) * rimWidth * .31;
+          const y = brothY + Math.sin(angle) * rimWidth * .115;
+          ellipsePath(x, y, rimWidth * .034, rimWidth * .042);
+          ctx.fill();
+          ctx.strokeStyle = 'rgba(129, 65, 17, .52)';
+          ctx.lineWidth = rimWidth * .007;
+          ctx.stroke();
+        }
+
+        drawMushroom(cx + rimWidth * .3 + sway, brothY - rimWidth * .035, rimWidth * .115, -.12);
+        drawMushroom(cx + rimWidth * .41 + sway, brothY + rimWidth * .08, rimWidth * .092, .16);
+        drawTofu(cx - rimWidth * .05 + sway, brothY - rimWidth * .17, rimWidth * .12, -.13);
+        drawTofu(cx + rimWidth * .16 + sway, brothY + rimWidth * .11, rimWidth * .105, .16);
+
+        // Scallions catch the light with two small, vivid arcs.
+        ctx.save();
+        ctx.strokeStyle = '#9dbb65';
+        ctx.lineCap = 'round';
+        ctx.lineWidth = rimWidth * .018;
+        [[-.2, -.21, -.03, -.37], [.01, .2, .2, .04], [.18, -.05, .39, -.2]].forEach((line) => {
+          ctx.beginPath();
+          ctx.moveTo(cx + line[0] * rimWidth, brothY + line[1] * rimWidth);
+          ctx.quadraticCurveTo(cx + (line[0] + .06) * rimWidth, brothY + (line[1] - .06) * rimWidth, cx + line[2] * rimWidth, brothY + line[3] * rimWidth);
+          ctx.stroke();
+        });
+        ctx.restore();
+      }
+
+      function drawBowl(cx, bowlTop, rimWidth, time) {
+        const rimHeight = rimWidth * .205;
+        const bodyBottom = bowlTop + rimWidth * .55;
+        const brothY = bowlTop + rimHeight * .06;
+        const brothRX = rimWidth * .435;
+        const brothRY = rimHeight * .41;
+
+        ctx.save();
+        ctx.translate(pointer.x * rimWidth * .018, pointer.y * rimWidth * .012);
+
+        // The earthenware body.
+        const body = ctx.createLinearGradient(cx, bowlTop, cx, bodyBottom);
+        body.addColorStop(0, '#73351f');
+        body.addColorStop(.23, '#55261b');
+        body.addColorStop(.72, '#2b1815');
+        body.addColorStop(1, '#170f0e');
+        ctx.fillStyle = body;
+        ctx.beginPath();
+        ctx.moveTo(cx - rimWidth * .49, bowlTop + rimHeight * .02);
+        ctx.bezierCurveTo(cx - rimWidth * .47, bowlTop + rimHeight * .7, cx - rimWidth * .39, bodyBottom - rimWidth * .02, cx, bodyBottom);
+        ctx.bezierCurveTo(cx + rimWidth * .39, bodyBottom - rimWidth * .02, cx + rimWidth * .47, bowlTop + rimHeight * .7, cx + rimWidth * .49, bowlTop + rimHeight * .02);
+        ctx.closePath();
+        ctx.fill();
+
+        const bodyGlow = ctx.createLinearGradient(cx - rimWidth * .42, bowlTop, cx + rimWidth * .12, bodyBottom);
+        bodyGlow.addColorStop(0, 'rgba(225, 104, 49, .19)');
+        bodyGlow.addColorStop(.46, 'rgba(145, 54, 27, .08)');
+        bodyGlow.addColorStop(1, 'rgba(0, 0, 0, 0)');
+        ctx.fillStyle = bodyGlow;
+        ctx.fill();
+
+        ctx.strokeStyle = 'rgba(246, 138, 72, .24)';
+        ctx.lineWidth = rimWidth * .012;
+        ctx.beginPath();
+        ctx.moveTo(cx - rimWidth * .458, bowlTop + rimHeight * .18);
+        ctx.bezierCurveTo(cx - rimWidth * .42, bowlTop + rimHeight * .7, cx - rimWidth * .32, bodyBottom - rimWidth * .06, cx - rimWidth * .04, bodyBottom - rimWidth * .028);
+        ctx.stroke();
+
+        // A quiet reflection on the bowl's lower curve.
+        ctx.strokeStyle = 'rgba(255, 187, 112, .14)';
+        ctx.lineWidth = rimWidth * .022;
+        ctx.beginPath();
+        ctx.bezierCurveTo(cx - rimWidth * .21, bodyBottom - rimWidth * .07, cx + rimWidth * .1, bodyBottom - rimWidth * .035, cx + rimWidth * .28, bodyBottom - rimWidth * .16);
+        ctx.stroke();
+
+        // Thick ceramic rim.
+        const rim = ctx.createRadialGradient(cx - rimWidth * .15, bowlTop - rimHeight * .1, 0, cx, bowlTop, rimWidth * .6);
+        rim.addColorStop(0, '#aa5a32');
+        rim.addColorStop(.48, '#74341f');
+        rim.addColorStop(1, '#321819');
+        ctx.fillStyle = rim;
+        ellipsePath(cx, bowlTop, rimWidth * .515, rimHeight * .59);
+        ctx.fill();
+        ctx.strokeStyle = 'rgba(239, 130, 69, .31)';
+        ctx.lineWidth = rimWidth * .014;
+        ctx.stroke();
+
+        // Broth, with a soft hot center.
+        const broth = ctx.createRadialGradient(cx - rimWidth * .14, brothY - brothRY * .38, rimWidth * .04, cx, brothY, brothRX * 1.18);
+        broth.addColorStop(0, '#c96a25');
+        broth.addColorStop(.33, '#a94618');
+        broth.addColorStop(.75, '#672516');
+        broth.addColorStop(1, '#351517');
+        ctx.fillStyle = broth;
+        ellipsePath(cx, brothY, brothRX, brothRY);
+        ctx.fill();
+
+        ctx.save();
+        ellipsePath(cx, brothY, brothRX, brothRY);
+        ctx.clip();
+        const soupGlow = ctx.createRadialGradient(cx - rimWidth * .18, brothY - brothRY * .48, 0, cx, brothY, brothRX);
+        soupGlow.addColorStop(0, 'rgba(255, 206, 127, .21)');
+        soupGlow.addColorStop(.5, 'rgba(255, 130, 34, .035)');
+        soupGlow.addColorStop(1, 'rgba(24, 5, 4, .2)');
+        ctx.fillStyle = soupGlow;
+        ctx.fillRect(cx - brothRX, brothY - brothRY, brothRX * 2, brothRY * 2);
+        ctx.restore();
+
+        drawNoodles(cx, brothY, brothRX, brothRY, rimWidth, time);
+        drawGreens(cx, brothY, rimWidth, time);
+
+        // Rim highlight foreground, to seat the ingredients inside the bowl.
+        ctx.strokeStyle = 'rgba(255, 176, 99, .24)';
+        ctx.lineWidth = rimWidth * .017;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop - rimHeight * .008, rimWidth * .474, rimHeight * .475, 0, .08, Math.PI - .08);
+        ctx.stroke();
+        ctx.strokeStyle = 'rgba(21, 9, 8, .64)';
+        ctx.lineWidth = rimWidth * .025;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop + rimHeight * .018, rimWidth * .466, rimHeight * .446, 0, 0, TAU);
+        ctx.stroke();
+        ctx.strokeStyle = 'rgba(230, 119, 63, .21)';
+        ctx.lineWidth = rimWidth * .009;
+        ctx.beginPath();
+        ctx.ellipse(cx, bowlTop - rimHeight * .008, rimWidth * .49, rimHeight * .53, 0, .12, Math.PI - .12);
+        ctx.stroke();
+
+        ctx.restore();
+      }
+
+      function draw(time) {
+        ctx.clearRect(0, 0, width, height);
+
+        const rimWidth = clamp(Math.min(width * .78, height * .70), 250, 570);
+        const cx = width * .5 + pointer.x * Math.min(width * .032, 25);
+        const bowlTop = height * .54 + pointer.y * Math.min(height * .018, 15);
+        const adjustedWidth = rimWidth;
+
+        drawBackgroundGlow(cx, bowlTop, adjustedWidth);
+        drawShadow(cx, bowlTop, adjustedWidth);
+        drawSteam(cx, bowlTop, adjustedWidth, time);
+        drawBowl(cx, bowlTop, adjustedWidth, time);
+
+        // Tiny warm reflection under the silhouette anchors it in the dark.
+        const reflection = ctx.createRadialGradient(cx, bowlTop + adjustedWidth * .58, 0, cx, bowlTop + adjustedWidth * .58, adjustedWidth * .48);
+        reflection.addColorStop(0, 'rgba(182, 63, 20, .07)');
+        reflection.addColorStop(1, 'rgba(182, 63, 20, 0)');
+        ctx.fillStyle = reflection;
+        ellipsePath(cx, bowlTop + adjustedWidth * .58, adjustedWidth * .5, adjustedWidth * .08);
+        ctx.fill();
+      }
+
+      function render(time) {
+        draw(time * .001);
+      }
+
+      function animate(time) {
+        if (!lastTime) lastTime = time;
+        const elapsed = Math.min(time - lastTime, 50);
+        lastTime = time;
+        pointer.x += (pointer.targetX - pointer.x) * Math.min(1, elapsed * .008);
+        pointer.y += (pointer.targetY - pointer.y) * Math.min(1, elapsed * .008);
+        render(time);
+        frameId = window.requestAnimationFrame(animate);
+      }
+
+      function setPointer(event) {
+        pointer.targetX = (event.clientX / width - .5) * 2;
+        pointer.targetY = (event.clientY / height - .5) * 2;
+      }
+
+      window.addEventListener('resize', resize, { passive: true });
+      window.addEventListener('pointermove', setPointer, { passive: true });
+      window.addEventListener('pointerleave', () => {
+        pointer.targetX = 0;
+        pointer.targetY = 0;
+      }, { passive: true });
+      reduceQuery.addEventListener('change', (event) => {
+        reducedMotion = event.matches;
+        if (reducedMotion) {
+          window.cancelAnimationFrame(frameId);
+          pointer.x = 0;
+          pointer.y = 0;
+          render(0);
+        } else {
+          lastTime = 0;
+          frameId = window.requestAnimationFrame(animate);
+        }
+      });
+
+      resize();
+      if (!reducedMotion) {
+        frameId = window.requestAnimationFrame(animate);
+      }
+    })();
+  </script>
+</body>
+</html>
